ns16:scriptTask.ns16:script:
//tw.local.amntList = 1; // for testing error handling
tw.local.amntList = [];
tw.local.inputList = [];
tw.local.hasFixedRate = false;

if (tw.local.requestType == tw.epv.RequestType.Amendment+"") {
	tw.local.event = "AMND";
	tw.local.eventCode = "AMND";
}else if (tw.local.requestType == tw.epv.RequestType.Collection+""){
	tw.local.eventCode = "LIQD";
}else{
	tw.local.eventCode = "INIT";
}

var j =0;
tw.local.charges = [];
//tw.local.charges = 4;

if (tw.local.InterestAndChargesList.listLength > 0) {

	for (var i=0; i<tw.local.InterestAndChargesList.listLength ; i++) {
	
		if (tw.local.InterestAndChargesList[i].ruleType == "Charge"){
		
			tw.local.charges[j] = {};
			tw.local.charges[j].defaultCurrency = {};
			tw.local.charges[j].component = tw.local.InterestAndChargesList[i].component;
			tw.local.charges[j].description = tw.local.InterestAndChargesList[i].description;
			tw.local.charges[j].rateType = tw.local.InterestAndChargesList[i].rateType;
			tw.local.charges[j].waiver = false;
			tw.local.charges[j].debitedAmount = {};
			tw.local.charges[j].debitedAccount = {};
			tw.local.charges[j].debitedAccount.currency = {};
			tw.local.charges[j].debitedAccount.accountClass = {};
			tw.local.charges[j].debitedAccount.accountClass.name = "001";
			tw.local.charges[j].debitedAccount.isOverDraft = null;
//			tw.local.charges[j].debitedAccount.accountClass.name = "Customer Account";

//			tw.local.charges[j].bookingCcy = tw.local.InterestAndChargesList[i].bookingCcy;
//			tw.local.charges[j].basisAmntCcy = tw.local.InterestAndChargesList[i].basisAmountCurrency;
	
	      //FLAT AMOUNT-----------------------------------------------------------------------------------------------
		if (tw.local.InterestAndChargesList[i].rateType == "Flat Amount") {
		
			var flatAmnt = tw.local.InterestAndChargesList[i].flatAmount;
			var basisAmntCcy = tw.local.InterestAndChargesList[i].basisAmountCurrency;
			var bookingCcy = tw.local.InterestAndChargesList[i].bookingCcy;
			var requestCcy = tw.local.requestCcy;
			
			tw.local.charges[j].defaultCurrency.name =  basisAmntCcy;
			tw.local.charges[j].defaultCurrency.value =  basisAmntCcy;
			
			tw.local.charges[j].flatAmount = flatAmnt;
			tw.local.charges[j].defaultAmount = Number(flatAmnt.toFixed(2));
			tw.local.charges[j].changeAmount = Number(flatAmnt.toFixed(2));
			
			//Contract CCY - Charge CCY (changed on 1.6)
//			if (bookingCcy === "Charge CCY") {
//				tw.local.charges[j].defaultCurrency.name =  basisAmntCcy;//###########################################BasicAmountCcy
//				tw.local.charges[j].defaultCurrency.value =  basisAmntCcy;
//				
//				tw.local.charges[j].defaultAmount = Number(flatAmnt.toFixed(2));
//				tw.local.charges[j].changeAmount = Number(flatAmnt.toFixed(2));
//				
//			}else if(bookingCcy === "Contract CCY"){
//				tw.local.charges[j].defaultCurrency.name =  requestCcy;//###########################################RequestCcy
//				tw.local.charges[j].defaultCurrency.value =  requestCcy;
//				
//				tw.local.charges[j].flatAmount = flatAmnt;
//				tw.local.charges[j].defaultAmount = Number(flatAmnt.toFixed(2));
//				tw.local.charges[j].changeAmount = Number(flatAmnt.toFixed(2));
//			}
		}
	        
	     //FIXED RATE---------------------------------------------------------------------------------------------------
	        if (tw.local.InterestAndChargesList[i].rateType == "Fixed Rate") {
	            tw.local.charges[j].defaultCurrency.name = requestCcy;
	            tw.local.charges[j].defaultCurrency.value = requestCcy;
	            
			tw.local.charges[j].defaultPercentage = tw.local.InterestAndChargesList[i].rate;
			tw.local.charges[j].changePercentage = tw.local.InterestAndChargesList[i].rate;
			tw.local.hasFixedRate = true;
	        }
	        j+=1;
	    }
	}
	
	
}else{
	tw.local.noDataMessage = "No Valid Charges Found";
}
